// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *Theme) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *Theme) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var codeVal types.Code
		if v, exists := pkMap["code"]; exists {
			switch val := v.(type) {
			case types.Code:
				codeVal = val
			case string:
				codeVal = types.NewCode(val)
			}
		}
		return t.GetByPK(codeVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case types.Code:
		return t.GetByPK(pk)
	case string:
		return t.GetByPK(types.NewCode(pk))
	}

	fmt.Printf("Error: Invalid primary key type for Theme.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *Theme) GetByPK(code types.Code) bool {
	tableName := ThemeTableName
	var codeNull sql.NullString
	var nameNull sql.NullString
	var modeInt int
	var repo_urlNull sql.NullString
	var repo_refNull sql.NullString
	var commit_shaNull sql.NullString
	var authorNull sql.NullString
	var tokensNull sql.NullString
	var wallpapersVal int
	var installed_byNull sql.NullString
	var installed_atNull sql.NullString
	var updated_atNull sql.NullString

	// Collect arguments for query
	args := []interface{}{
		code,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT code, name, mode, repo_url, repo_ref, commit_sha, author, tokens, wallpapers, installed_by, installed_at, updated_at FROM "%s" WHERE 1=1 AND code = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&codeNull,
		&nameNull,
		&modeInt,
		&repo_urlNull,
		&repo_refNull,
		&commit_shaNull,
		&authorNull,
		&tokensNull,
		&wallpapersVal,
		&installed_byNull,
		&installed_atNull,
		&updated_atNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Theme: %v\n", err)
		return false
	}

	// Populate fields
	t.Code = types.NewCode(codeNull.String)
	t.Name = types.NewText(nameNull.String)
	t.Mode = ThemeMode(modeInt)
	t.Repo_url = types.NewText(repo_urlNull.String)
	t.Repo_ref = types.NewText(repo_refNull.String)
	t.Commit_sha = types.NewText(commit_shaNull.String)
	t.Author = types.NewText(authorNull.String)
	t.Tokens = types.NewText(tokensNull.String)
	t.Wallpapers = wallpapersVal
	t.Installed_by = types.NewCode(installed_byNull.String)
	t.Installed_at, _ = types.NewDateTimeFromString(installed_atNull.String)
	t.Updated_at, _ = types.NewDateTimeFromString(updated_atNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *Theme) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := ThemeTableName

	// Collect arguments for INSERT
	args := []interface{}{
		t.Code,
		t.Name,
		t.Mode,
		t.Repo_url,
		t.Repo_ref,
		t.Commit_sha,
		t.Author,
		t.Tokens,
		t.Wallpapers,
		t.Installed_by,
		t.Installed_at,
		t.Updated_at,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (code, name, mode, repo_url, repo_ref, commit_sha, author, tokens, wallpapers, installed_by, installed_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (code) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Theme: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ThemeTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Theme) InsertAll(records []*Theme, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Code,
			r.Name,
			r.Mode,
			r.Repo_url,
			r.Repo_ref,
			r.Commit_sha,
			r.Author,
			r.Tokens,
			r.Wallpapers,
			r.Installed_by,
			r.Installed_at,
			r.Updated_at,
		})
	}
	tableName := ThemeTableName
	columns := []string{"code", "name", "mode", "repo_url", "repo_ref", "commit_sha", "author", "tokens", "wallpapers", "installed_by", "installed_at", "updated_at"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *Theme) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := ThemeTableName

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			setClauses = append(setClauses, "code = ?")
			values = append(values, t.Code)
		}
		if t.hasFieldChanged("name") {
			setClauses = append(setClauses, "name = ?")
			values = append(values, t.Name)
		}
		if t.hasFieldChanged("mode") {
			setClauses = append(setClauses, "mode = ?")
			values = append(values, t.Mode)
		}
		if t.hasFieldChanged("repo_url") {
			setClauses = append(setClauses, "repo_url = ?")
			values = append(values, t.Repo_url)
		}
		if t.hasFieldChanged("repo_ref") {
			setClauses = append(setClauses, "repo_ref = ?")
			values = append(values, t.Repo_ref)
		}
		if t.hasFieldChanged("commit_sha") {
			setClauses = append(setClauses, "commit_sha = ?")
			values = append(values, t.Commit_sha)
		}
		if t.hasFieldChanged("author") {
			setClauses = append(setClauses, "author = ?")
			values = append(values, t.Author)
		}
		if t.hasFieldChanged("tokens") {
			setClauses = append(setClauses, "tokens = ?")
			values = append(values, t.Tokens)
		}
		if t.hasFieldChanged("wallpapers") {
			setClauses = append(setClauses, "wallpapers = ?")
			values = append(values, t.Wallpapers)
		}
		if t.hasFieldChanged("installed_by") {
			setClauses = append(setClauses, "installed_by = ?")
			values = append(values, t.Installed_by)
		}
		if t.hasFieldChanged("installed_at") {
			setClauses = append(setClauses, "installed_at = ?")
			values = append(values, t.Installed_at)
		}
		if t.hasFieldChanged("updated_at") {
			setClauses = append(setClauses, "updated_at = ?")
			values = append(values, t.Updated_at)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "name = ?")
		values = append(values, t.Name)
		setClauses = append(setClauses, "mode = ?")
		values = append(values, t.Mode)
		setClauses = append(setClauses, "repo_url = ?")
		values = append(values, t.Repo_url)
		setClauses = append(setClauses, "repo_ref = ?")
		values = append(values, t.Repo_ref)
		setClauses = append(setClauses, "commit_sha = ?")
		values = append(values, t.Commit_sha)
		setClauses = append(setClauses, "author = ?")
		values = append(values, t.Author)
		setClauses = append(setClauses, "tokens = ?")
		values = append(values, t.Tokens)
		setClauses = append(setClauses, "wallpapers = ?")
		values = append(values, t.Wallpapers)
		setClauses = append(setClauses, "installed_by = ?")
		values = append(values, t.Installed_by)
		setClauses = append(setClauses, "installed_at = ?")
		values = append(values, t.Installed_at)
		setClauses = append(setClauses, "updated_at = ?")
		values = append(values, t.Updated_at)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Code)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			renamed = append(renamed, renamedKey{"code", t.oldValues["code"], t.Code})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND code = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Theme: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Theme: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *Theme) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Code.Equal(old)
		}
	case "name":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Name.Equal(old)
		}
	case "mode":
		if old, ok := oldValue.(ThemeMode); ok {
			return t.Mode != old
		}
	case "repo_url":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Repo_url.Equal(old)
		}
	case "repo_ref":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Repo_ref.Equal(old)
		}
	case "commit_sha":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Commit_sha.Equal(old)
		}
	case "author":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Author.Equal(old)
		}
	case "tokens":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Tokens.Equal(old)
		}
	case "wallpapers":
		if old, ok := oldValue.(int); ok {
			return t.Wallpapers != old
		}
		return true // Type mismatch, assume changed
	case "installed_by":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Installed_by.Equal(old)
		}
	case "installed_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Installed_at.Equal(old)
		}
	case "updated_at":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Updated_at.Equal(old)
		}
	}

	return false
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Theme) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Theme) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"Theme_Asset", true, "theme_code", "", 0}, {"User_Theme", true, "theme_code", "", 0}},
	}
	var companies []string
	rows, err := t.db.Query(`SELECT name FROM "Company"`)
	if err != nil {
		return err
	}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			rows.Close()
			return err
		}
		companies = append(companies, name)
	}
	rows.Close()
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

