// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *Theme) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := ThemeTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT code, name, mode, repo_url, repo_ref, commit_sha, author, tokens, wallpapers, installed_by, installed_at, updated_at FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Theme: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *Theme) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var codeNull sql.NullString
		var nameNull sql.NullString
		var modeInt int
		var repo_urlNull sql.NullString
		var repo_refNull sql.NullString
		var commit_shaNull sql.NullString
		var authorNull sql.NullString
		var tokensNull sql.NullString
		var installed_byNull sql.NullString
		var installed_atNull sql.NullString
		var updated_atNull sql.NullString

		err := t.currentRows.Scan(
			&codeNull,
			&nameNull,
			&modeInt,
			&repo_urlNull,
			&repo_refNull,
			&commit_shaNull,
			&authorNull,
			&tokensNull,
			&t.Wallpapers,
			&installed_byNull,
			&installed_atNull,
			&updated_atNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Theme record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Code = types.NewCode(codeNull.String)
		t.Name = types.NewText(nameNull.String)
		t.Mode = ThemeMode(modeInt)
		t.Repo_url = types.NewText(repo_urlNull.String)
		t.Repo_ref = types.NewText(repo_refNull.String)
		t.Commit_sha = types.NewText(commit_shaNull.String)
		t.Author = types.NewText(authorNull.String)
		t.Tokens = types.NewText(tokensNull.String)
		t.Installed_by = types.NewCode(installed_byNull.String)
		t.Installed_at, _ = types.NewDateTimeFromString(installed_atNull.String)
		t.Updated_at, _ = types.NewDateTimeFromString(updated_atNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *Theme) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := ThemeTableName
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT code, name, mode, repo_url, repo_ref, commit_sha, author, tokens, wallpapers, installed_by, installed_at, updated_at FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Theme: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &Theme{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var codeNull sql.NullString
		var nameNull sql.NullString
		var modeInt int
		var repo_urlNull sql.NullString
		var repo_refNull sql.NullString
		var commit_shaNull sql.NullString
		var authorNull sql.NullString
		var tokensNull sql.NullString
		var installed_byNull sql.NullString
		var installed_atNull sql.NullString
		var updated_atNull sql.NullString

		err := rows.Scan(
			&codeNull,
			&nameNull,
			&modeInt,
			&repo_urlNull,
			&repo_refNull,
			&commit_shaNull,
			&authorNull,
			&tokensNull,
			&record.Wallpapers,
			&installed_byNull,
			&installed_atNull,
			&updated_atNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Theme record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Code = types.NewCode(codeNull.String)
		record.Name = types.NewText(nameNull.String)
		record.Mode = ThemeMode(modeInt)
		record.Repo_url = types.NewText(repo_urlNull.String)
		record.Repo_ref = types.NewText(repo_refNull.String)
		record.Commit_sha = types.NewText(commit_shaNull.String)
		record.Author = types.NewText(authorNull.String)
		record.Tokens = types.NewText(tokensNull.String)
		record.Installed_by = types.NewCode(installed_byNull.String)
		record.Installed_at, _ = types.NewDateTimeFromString(installed_atNull.String)
		record.Updated_at, _ = types.NewDateTimeFromString(updated_atNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Theme records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *Theme) copyFromBuffered(record *Theme) {
	t.Code = record.Code
	t.Name = record.Name
	t.Mode = record.Mode
	t.Repo_url = record.Repo_url
	t.Repo_ref = record.Repo_ref
	t.Commit_sha = record.Commit_sha
	t.Author = record.Author
	t.Tokens = record.Tokens
	t.Wallpapers = record.Wallpapers
	t.Installed_by = record.Installed_by
	t.Installed_at = record.Installed_at
	t.Updated_at = record.Updated_at
	t.StoreOldValues()
}

